ON CONFLICT (id) DO NOTHING;
































-- Whoever already signed up on this install gets the demo workspace too.
SELECT 'f8c10df0-e4aa-4e30-a1b0-90847b243e08', u.id, 'admin'::public.workspace_role
  FROM public.users u
 WHERE u.team_id <> 'b03d2eb6-1175-4dcf-a362-a24c36886106'
ON CONFLICT (workspace_id, user_id) DO NOTHING;

-- And to the demo team as an admin: Settings -> Members reads the team, so without this the
-- page answers 403 in the demo workspace. demo-reset.sql drops it with the team (cascade).
SELECT 'b03d2eb6-1175-4dcf-a362-a24c36886106', u.id, 'admin'
  FROM public.users u
 WHERE u.team_id <> 'b03d2eb6-1175-4dcf-a362-a24c36886106'
ON CONFLICT (team_id, user_id) DO NOTHING;

-- Fill the flattened rows the Accounts list and the Graph read.
SELECT * FROM public.refresh_entity_list_rows('f8c10df0-e4aa-4e30-a1b0-90847b243e08');

